package dev.umbral.test;
import dev.umbral.UmbralContent;
import dev.umbral.access.*;
import dev.umbral.block.*;
import dev.umbral.fence.*;
import dev.umbral.installation.*;
import dev.umbral.network.*;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.util.ProblemReporter;
import net.minecraft.world.entity.EntityTypes;
import net.minecraft.world.item.*;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.storage.TagValueInput;
import net.minecraft.world.phys.Vec3;
import java.util.*;

public final class FenceGameTests {
    static final String S="umbral-test:network";
    static final BlockPos CORE=new BlockPos(1,1,1),FENCE=new BlockPos(4,1,4);
    record Setup(ServerPlayer owner,DeviceBlockEntity core,DeviceBlockEntity fence,DeviceBlockEntity next){}
    DeviceBlockEntity put(GameTestHelper t,BlockPos p,DeviceBlock b,ServerPlayer owner){t.setBlock(p,b);var d=t.getBlockEntity(p,DeviceBlockEntity.class);d.initializeOwner(owner.getUUID(),"Perímetro");return d;}
    Setup setup(GameTestHelper t){for(int x=0;x<10;x++)for(int z=0;z<10;z++)t.setBlock(new BlockPos(x,0,z),Blocks.STONE);var p=(ServerPlayer)t.makeMockServerPlayer(GameType.SURVIVAL);var c=put(t,CORE,UmbralContent.CORE,p);var f=put(t,FENCE,UmbralContent.FENCE,p);var n=put(t,FENCE.east(),UmbralContent.FENCE,p);p.setPos(Vec3.atCenterOf(f.getBlockPos()).add(0,0,-2));return new Setup(p,c,f,n);}
    void pair(GameTestHelper t,Setup i){t.assertTrue(FenceService.pair(i.owner,i.fence,i.core).equals("fence_paired"),"Owned physical line pairs");}
    void afterTick(GameTestHelper t,Runnable r){t.runAfterDelay(10,r);}
    NexoProtocol.Request request(Setup i,NexoProtocol.Operation op){return new NexoProtocol.Request(i.fence.getBlockPos(),i.fence.identity(),i.fence.link(),8,op,i.fence.getBlockPos(),i.fence.identity());}
    @GameTest(structure=S) public void pairingCreatesOneFeederAndOneDirectoryEntry(GameTestHelper t){var i=setup(t);pair(t,i);t.assertTrue(FenceService.head(i.fence)&&!FenceService.head(i.next),"Only explicit section is feeder");t.assertTrue(i.fence.fence().segments==2&&i.next.fence().source().equals(i.fence.asDoorTarget()),"Whole line shares controller");t.assertTrue(InstallationDirectory.get(t.getLevel()).entries(i.owner.getUUID(),i.core.link()).stream().filter(e->e.kind()==DeviceKind.FENCE).count()==1,"Line occupies one directory entry");t.assertFalse(i.fence.fence().armed(),"Pairing never energizes implicitly");t.succeed();}
    @GameTest(structure=S) public void adjacentSectionsConnectAndUseFenceHeight(GameTestHelper t){var i=setup(t);t.assertTrue(i.fence.getBlockState().getValue(ElectricFenceBlock.CONNECTIONS.get(Direction.EAST)),"Neighbor joins post");t.assertTrue(ElectricFenceBlock.body(i.fence.getBlockState(),true).bounds().maxY==1.5,"Vanilla fence collision height");t.setBlock(FENCE.north(),Blocks.STONE);t.assertTrue(i.fence.getBlockState().getValue(ElectricFenceBlock.CONNECTIONS.get(Direction.NORTH)),"Full wall joins");t.succeed();}
    @GameTest(structure=S,maxTicks=60) public void armDisarmPropagatesToWholeLine(GameTestHelper t){var i=setup(t);pair(t,i);t.assertTrue(FenceService.arm(i.fence,true).equals("armed"),"Online feeder arms");afterTick(t,()->{t.assertTrue(i.fence.getBlockState().getValue(ElectricFenceBlock.ENERGIZED)&&i.next.getBlockState().getValue(ElectricFenceBlock.ENERGIZED),"Both pieces energized");FenceService.arm(i.fence,false);t.assertFalse(i.next.getBlockState().getValue(ElectricFenceBlock.ENERGIZED),"Disarm removes energy immediately");t.succeed();});}
    @GameTest(structure=S,maxTicks=80) public void redstoneNeedsArmedMasterAndPhysicalSignal(GameTestHelper t){var i=setup(t);pair(t,i);i.fence.fence().redstone(true);FenceService.arm(i.fence,true);afterTick(t,()->{t.assertFalse(i.fence.getBlockState().getValue(ElectricFenceBlock.ENERGIZED),"Armed without signal stays inactive");t.setBlock(FENCE.north(),Blocks.REDSTONE_BLOCK);afterTick(t,()->{t.assertTrue(i.next.getBlockState().getValue(ElectricFenceBlock.ENERGIZED),"Signal energizes line");FenceService.arm(i.fence,false);t.assertFalse(i.next.getBlockState().getValue(ElectricFenceBlock.ENERGIZED),"Master disarm overrides signal");t.succeed();});});}
    @GameTest(structure=S,maxTicks=80) public void networkOutageStopsRealContactDamage(GameTestHelper t){var i=setup(t);pair(t,i);FenceService.arm(i.fence,true);afterTick(t,()->{t.setBlock(CORE,Blocks.AIR);NetworkService.invalidate(t.getLevel());afterTick(t,()->{t.assertFalse(i.next.getBlockState().getValue(ElectricFenceBlock.ENERGIZED),"Loss of network powers off line");t.succeed();});});}
    @GameTest(structure=S,maxTicks=80) public void cutOffPiecesLoseEnergyAndNetwork(GameTestHelper t){var i=setup(t);var end=put(t,FENCE.east(2),UmbralContent.FENCE,i.owner);pair(t,i);FenceService.arm(i.fence,true);afterTick(t,()->{t.setBlock(FENCE.east(),Blocks.AIR);t.runAfterDelay(20,()->{t.assertFalse(end.getBlockState().getValue(ElectricFenceBlock.ENERGIZED),"Isolated side expires");t.assertFalse(NetworkService.inspect(t.getLevel(),end).online(),"Isolated side cannot act as remote console");t.succeed();});});}
    @GameTest(structure=S,maxTicks=80) public void destroyingFeederStopsPassivePieces(GameTestHelper t){var i=setup(t);pair(t,i);FenceService.arm(i.fence,true);afterTick(t,()->{t.setBlock(FENCE,Blocks.AIR);t.runAfterDelay(20,()->{t.assertFalse(i.next.getBlockState().getValue(ElectricFenceBlock.ENERGIZED),"No stale energized wire");t.succeed();});});}
    @GameTest(structure=S,maxTicks=80) public void ownedExtensionJoinsWithoutPairingAgain(GameTestHelper t){var i=setup(t);pair(t,i);FenceService.arm(i.fence,true);var end=put(t,FENCE.east(2),UmbralContent.FENCE,i.owner);afterTick(t,()->{t.assertTrue(end.link().equals(i.core.link())&&end.fence().source().equals(i.fence.asDoorTarget()),"New connected section enrolled");t.assertTrue(end.getBlockState().getValue(ElectricFenceBlock.ENERGIZED),"Extension inherits energy");t.succeed();});}
    @GameTest(structure=S) public void foreignSectionsAreNeverClaimed(GameTestHelper t){var i=setup(t);var p=(ServerPlayer)t.makeMockServerPlayer(GameType.SURVIVAL);var foreign=put(t,FENCE.east(2),UmbralContent.FENCE,p);pair(t,i);t.assertTrue(foreign.link()==null&&foreign.fence().source()==null,"Foreign line untouched");t.assertTrue(i.fence.fence().segments==2,"Stops at owner boundary");t.succeed();}
    @GameTest(structure=S) public void armedCircuitsCannotBeMergedByPairing(GameTestHelper t){var i=setup(t);pair(t,i);FenceService.arm(i.fence,true);t.assertTrue(FenceService.pair(i.owner,i.next,i.core).equals("fence_disarm_first"),"Armed circuit cannot be reassigned");t.assertTrue(FenceService.head(i.fence),"Original feeder preserved");t.succeed();}
    @GameTest(structure=S) public void oversizedLineRejectedWithoutPartialBinding(GameTestHelper t){var i=setup(t);for(int y=1;y<=9;y++)for(int x=4;x<=7;x++)for(int z=4;z<=7;z++)put(t,new BlockPos(x,y,z),UmbralContent.FENCE,i.owner);var start=t.getBlockEntity(FENCE,DeviceBlockEntity.class);t.assertTrue(FenceService.pair(i.owner,start,i.core).equals("fence_limit"),"More than 128 rejected");t.assertTrue(start.link()==null&&start.fence().source()==null,"Rejection is atomic");t.succeed();}
    @GameTest(structure=S) public void playersAreExcludedByDefaultAndBearerPassesExempt(GameTestHelper t){var i=setup(t);pair(t,i);var guest=(ServerPlayer)t.makeMockServerPlayer(GameType.SURVIVAL);t.assertFalse(FenceService.eligible(t.getLevel(),i.fence,guest),"Default PvE mode");i.fence.fence().cycle();t.assertTrue(FenceService.eligible(t.getLevel(),i.fence,guest)==t.getLevel().isPvpAllowed(),"Intruders respects PvP");t.assertFalse(FenceService.eligible(t.getLevel(),i.fence,i.owner),"Owner exempt");var grant=AccessRegistry.get(t.getLevel()).issue(i.owner.getUUID(),i.core.link(),"Invitado");var card=new ItemStack(UmbralContent.ACCESS_CARD);card.set(UmbralContent.CARD_ID,grant.id());guest.setItemInHand(net.minecraft.world.InteractionHand.OFF_HAND,card);t.assertFalse(FenceService.eligible(t.getLevel(),i.fence,guest),"Valid offhand pass exempt");AccessRegistry.get(t.getLevel()).revoke(grant.id(),i.owner.getUUID(),i.core.link());t.assertTrue(FenceService.eligible(t.getLevel(),i.fence,guest)==t.getLevel().isPvpAllowed(),"Revocation effective");t.succeed();}
    @GameTest(structure=S,maxTicks=60) public void liveWireDamagesMonsterWithoutConsumingInventory(GameTestHelper t){var i=setup(t);pair(t,i);var mob=t.spawn(EntityTypes.HUSK,FENCE.north());mob.setNoAi(true);mob.setPos(Vec3.atLowerCornerOf(i.fence.getBlockPos()).add(.5,0,.18));FenceService.arm(i.fence,true);t.runAfterDelay(7,()->{t.assertTrue(mob.getHealth()==mob.getMaxHealth()-4,"Real hostile takes two hearts at contact");t.runAfterDelay(5,()->{t.assertTrue(mob.getHealth()==mob.getMaxHealth()-4,"Shared cooldown prevents repeated contact hits");t.succeed();});});}
    @GameTest(structure=S) public void circuitSettingsSurviveReloadWithoutSavingEnergyHeartbeat(GameTestHelper t){var i=setup(t);pair(t,i);i.fence.fence().armed(true);i.fence.fence().redstone(true);i.fence.fence().cycle();var copy=new DeviceBlockEntity(i.fence.getBlockPos(),i.fence.getBlockState());copy.setLevel(t.getLevel());copy.loadWithComponents(TagValueInput.create(ProblemReporter.DISCARDING,t.getLevel().registryAccess(),i.fence.saveWithoutMetadata(t.getLevel().registryAccess())));t.assertTrue(FenceService.head(copy)&&copy.fence().armed()&&copy.fence().redstone()&&copy.fence().target()==FenceState.Target.INTRUDERS,"Saved controller settings");t.assertTrue(copy.fence().seen<0,"Contact heartbeat must be recomputed after load");t.succeed();}
    @GameTest(structure=S) public void nexoAuthenticatesFenceTargetsAndControl(GameTestHelper t){var i=setup(t);pair(t,i);t.assertTrue(NexoProtocol.handle(i.owner,request(i,NexoProtocol.Operation.RANGE)).result().equals("fence_mode"),"Owner changes targets");t.assertTrue(NexoProtocol.handle(i.owner,request(i,NexoProtocol.Operation.FENCE_CONTROL)).result().equals("fence_control"),"Owner changes control");var guest=(ServerPlayer)t.makeMockServerPlayer(GameType.SURVIVAL);guest.setPos(i.owner.position());t.assertFalse(NexoProtocol.handle(guest,request(i,NexoProtocol.Operation.ARM)).valid(),"Foreign command rejected");t.succeed();}
    @GameTest(structure=S) public void cableEntersOnlyPairedFeeder(GameTestHelper t){var i=setup(t);t.setBlock(FENCE.north(),UmbralContent.CABLE);t.setBlock(FENCE.east().north(),UmbralContent.CABLE);pair(t,i);t.assertTrue(t.getBlockState(FENCE.north()).getValue(CopperCableBlock.CONNECTIONS.get(Direction.SOUTH)),"Cable joins feeder socket");t.assertFalse(t.getBlockState(FENCE.east().north()).getValue(CopperCableBlock.CONNECTIONS.get(Direction.SOUTH)),"Passive segment has no network socket");t.succeed();}

    @GameTest(structure=S,maxTicks=60) public void oversizedExtensionStopsDischargeAndExplainsTheLimit(GameTestHelper t){var i=setup(t);for(int y=1;y<=8;y++)for(int x=4;x<=7;x++)for(int z=4;z<=7;z++)if(!new BlockPos(x,y,z).equals(FENCE)&&!new BlockPos(x,y,z).equals(FENCE.east()))put(t,new BlockPos(x,y,z),UmbralContent.FENCE,i.owner);pair(t,i);t.assertTrue(i.fence.fence().segments==128,"Exactly 128 can pair");FenceService.arm(i.fence,true);put(t,new BlockPos(4,9,4),UmbralContent.FENCE,i.owner);afterTick(t,()->{t.assertTrue(i.fence.fence().segments==129&&!i.fence.getBlockState().getValue(ElectricFenceBlock.ENERGIZED),"Oversize reported rather than silently truncating active circuit");t.assertTrue(FenceService.arm(i.fence,true).equals("fence_limit"),"Cannot force arm beyond limit");t.succeed();});}

    @GameTest(structure=S) public void longMeshRunKeepsOnlySparseStakesAndItsEndpoints(GameTestHelper t){var i=setup(t);for(int x=6;x<=10;x++)put(t,new BlockPos(x,1,4),UmbralContent.FENCE,i.owner);pair(t,i);long posts=java.util.stream.IntStream.rangeClosed(4,10).filter(x->t.getBlockState(new BlockPos(x,1,4)).getValue(ElectricFenceBlock.SUPPORT)).count();t.assertTrue(posts<=4,"Seven sections use at most four slim supports");t.assertTrue(i.fence.getBlockState().getValue(ElectricFenceBlock.SUPPORT)&&t.getBlockState(new BlockPos(10,1,4)).getValue(ElectricFenceBlock.SUPPORT),"Feeder and endpoint always supported");put(t,new BlockPos(7,1,3),UmbralContent.FENCE,i.owner);t.assertTrue(t.getBlockState(new BlockPos(7,1,4)).getValue(ElectricFenceBlock.SUPPORT),"A branch gains a support immediately");t.succeed();}
    @GameTest(structure=S) public void meshNoLongerHasInvisibleThickColumns(GameTestHelper t){var i=setup(t);t.assertTrue(ElectricFenceBlock.body(i.fence.getBlockState(),true).toAabbs().stream().noneMatch(b->b.contains(.35,.5,.35)),"Old chunky column footprint is free");var straight=i.fence.getBlockState().setValue(ElectricFenceBlock.SUPPORT,false).setValue(ElectricFenceBlock.FEEDER,false).setValue(ElectricFenceBlock.CONNECTIONS.get(Direction.EAST),true).setValue(ElectricFenceBlock.CONNECTIONS.get(Direction.WEST),true);t.assertTrue(ElectricFenceBlock.body(straight,true).bounds().getZsize()==.5/16,"Mesh collider is thin while retaining fence height");t.succeed();}
    @GameTest(structure=S,maxTicks=60) public void oldFenceStatesReconcileWithoutLosingCircuitOrOwnership(GameTestHelper t){var i=setup(t);for(int x=6;x<=10;x++)put(t,new BlockPos(x,1,4),UmbralContent.FENCE,i.owner);pair(t,i);for(int x=4;x<=10;x++){var pos=t.absolutePos(new BlockPos(x,1,4));var encoded=net.minecraft.world.level.block.state.BlockState.CODEC.encodeStart(com.mojang.serialization.JsonOps.INSTANCE,t.getLevel().getBlockState(pos)).getOrThrow().getAsJsonObject();encoded.getAsJsonObject("properties").remove("support");var state=net.minecraft.world.level.block.state.BlockState.CODEC.parse(com.mojang.serialization.JsonOps.INSTANCE,encoded).getOrThrow();t.assertTrue(state.getValue(ElectricFenceBlock.SUPPORT),"Missing legacy property has safe default");t.getLevel().setBlock(pos,state,net.minecraft.world.level.block.Block.UPDATE_CLIENTS|net.minecraft.world.level.block.Block.UPDATE_KNOWN_SHAPE);}t.runAfterDelay(10,()->{long posts=java.util.stream.IntStream.rangeClosed(4,10).filter(x->t.getBlockState(new BlockPos(x,1,4)).getValue(ElectricFenceBlock.SUPPORT)).count();t.assertTrue(posts<=4&&i.fence.fence().segments==7,"Normal tick updates legacy posts");t.assertTrue(FenceService.head(i.fence)&&i.next.link().equals(i.core.link())&&i.next.ownedBy(i.owner.getUUID()),"Saved ownership and circuit survive the visual update");t.succeed();});}

}
